25	/**
26	 * For each hour H (0–23), check if an RN shift covers it.
27	 * Handles overnight shifts (e.g. 22:00–06:00).
28	 */
29	function getRnCoverage(shiftsForDate) {
30	  const rnShifts = (shiftsForDate || []).filter(sh => sh.staffType === 'RN');
31	  return Array.from({ length: 24 }, (_, h) => {
32	    const covered = rnShifts.some(sh => {
33	      const [startH] = sh.startTime.split(':').map(Number);
34	      const [endH]   = sh.endTime.split(':').map(Number);
35	      if (endH <= startH) {
36	        // overnight: covers [startH, 24) and [0, endH)
37	        return h >= startH || h < endH;
38	      }
39	      return h >= startH && h < endH;
40	    });
41	    // find covering shifts for tooltip
42	    const coveringRns = rnShifts
43	      .filter(sh => {
44	        const [startH] = sh.startTime.split(':').map(Number);
45	        const [endH]   = sh.endTime.split(':').map(Number);
46	        if (endH <= startH) return h >= startH || h < endH;
47	        return h >= startH && h < endH;
48	      })
49	      .map(sh => `${sh.staffName} ${sh.startTime}–${sh.endTime}`);
50	    return { hour: h, covered, coveringRns };
51	  });
52	}
53	
54	function findGaps(coverage) {
55	  const gaps = [];
56	  let gapStart = null;
57	  for (let h = 0; h <= 24; h++) {
58	    const notCovered = h < 24 && !coverage[h].covered;
59	    if (notCovered && gapStart === null) {
60	      gapStart = h;
61	    } else if (!notCovered && gapStart !== null) {
62	      gaps.push({ start: gapStart, end: h });
63	      gapStart = null;
64	    }
65	  }
66	  return gaps;
67	}
