70	  const fmtH = h => {
71	    if (h === 0 || h === 24) return '12am';
72	    if (h === 12) return '12pm';
73	    return h < 12 ? `${h}am` : `${h - 12}pm`;
74	  };
75	  return `${fmtH(gap.start)}–${fmtH(gap.end)}`;
76	}
77	
78	function coveredHoursCount(coverage) {
79	  return coverage.filter(c => c.covered).length;
80	}
