261	              <table className="w-full text-sm min-w-[700px]">
262	                <thead>
263	                  <tr className="bg-gray-50 border-b border-gray-100">
264	                    {['Date','Total Minutes','Target','Compliance','RN Minutes','RN Target','RN %','Status','Penalty'].map(h => (
265	                      <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>
266	                    ))}
267	                  </tr>
268	                </thead>
269	                <tbody>
270	                  {periodData.days.map((day, idx) => (
271	                    <tr key={day.date} className={`border-b border-gray-50 hover:bg-green-50/20 transition-colors ${idx % 2 === 1 ? 'bg-gray-50/40' : ''}`}>
272	                      <td className="px-4 py-3 font-medium text-gray-900 whitespace-nowrap">{toDisplay(day.date)}</td>
273	                      <td className="px-4 py-3 text-gray-700">{day.totalMinutes.toLocaleString()}</td>
274	                      <td className="px-4 py-3 text-gray-500">{day.targetMinutes.toLocaleString()}</td>
275	                      <td className="px-4 py-3 font-semibold" style={{ color: day.ragStatus === 'GREEN' ? '#22c55e' : day.ragStatus === 'AMBER' ? '#f59e0b' : '#ef4444' }}>
276	                        {formatPct(day.compliancePct)}
277	                      </td>
278	                      <td className="px-4 py-3 text-gray-700">{day.rnMinutes.toLocaleString()}</td>
279	                      <td className="px-4 py-3 text-gray-500">{day.rnTargetMinutes.toLocaleString()}</td>
280	                      <td className="px-4 py-3 font-semibold" style={{ color: day.rnRagStatus === 'GREEN' ? '#22c55e' : day.rnRagStatus === 'AMBER' ? '#f59e0b' : '#ef4444' }}>
281	                        {formatPct(day.rnCompliancePct)}
282	                      </td>
283	                      <td className="px-4 py-3">
284	                        <span className={`px-2 py-0.5 rounded text-xs font-bold ${
285	                          day.ragStatus === 'GREEN' ? 'bg-green-100 text-green-700' :
286	                          day.ragStatus === 'AMBER' ? 'bg-amber-100 text-amber-700' :
287	                          'bg-red-100 text-red-700'
288	                        }`}>{day.ragStatus}</span>
289	                      </td>
290	                      <td className="px-4 py-3 font-medium" style={{ color: day.penaltyAmount > 0 ? '#ef4444' : '#6b7280' }}>
291	                        {day.penaltyAmount > 0 ? formatAUD(day.penaltyAmount) : '—'}
292	                      </td>
293	                    </tr>
294	                  ))}
295	                </tbody>
296	              </table>
297	            </div>
298	          </div>
299	
300	        </div>
301	      )}
302	
303	      {/* Empty state */}
304	      {!generated && (
305	        <div className="text-center py-20 bg-white rounded-xl border border-gray-100 shadow-sm">
306	          <FileText className="w-12 h-12 text-gray-300 mx-auto mb-3" />
307	          <p className="text-gray-500 font-medium">No report generated yet</p>
308	          <p className="text-sm text-gray-400 mt-1">Select a date range and click Generate Report</p>
309	        </div>
310	      )}
311	    </div>
312	  );
313	}
