                  e.days <= 7  ? 'bg-red-600 text-white'        :
                  e.days <= 30 ? 'bg-amber-500 text-white'      :
                                 'bg-yellow-400 text-yellow-900'
                }`}>
                  {e.days <= 0 ? 'Expired' : `${e.days} days`}
                </span>
              </div>
            ))}
          </div>

