1	/**
2	 * CareMinutes.ai — Australian Date Utilities
3	 *
4	 * All "today" logic must use the Australia/Sydney IANA timezone identifier.
5	 * This correctly handles AEST (UTC+10, April–October) and
6	 * AEDT (UTC+11, October–April, daylight saving) automatically —
7	 * no manual offset arithmetic needed.
8	 *
9	 * Safe to call on Node.js 18+ (server) and all modern browsers (client).
10	 */
11	
12	/**
13	 * Returns today's date in Australian Eastern Time as YYYY-MM-DD.
14	 * The 'en-CA' locale is used because it reliably emits that format.
15	 *
16	 * @returns {string} e.g. "2026-04-07"
17	 */
18	export function getAustralianToday() {
19	  return new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Sydney' });
20	}
21	
22	/**
23	 * Returns the current Australian time as a human-readable string.
24	 * Useful for logging and display.
25	 *
26	 * @returns {string} e.g. "07/04/2026, 07:00:00 AM"
27	 */
28	export function getAustralianNow() {
29	  return new Date().toLocaleString('en-AU', { timeZone: 'Australia/Sydney' });
30	}
31	
32	/**
33	 * Returns quarter metadata for any ISO date string (YYYY-MM-DD).
34	 *   Q1 = Jan–Mar  |  Q2 = Apr–Jun  |  Q3 = Jul–Sep  |  Q4 = Oct–Dec
35	 *
36	 * @param {string} isoDate — "YYYY-MM-DD"
37	 * @returns {{
38	 *   quarter: number,
39	 *   year: number,
40	 *   start: string,
41	 *   end: string,
42	 *   totalDays: number,
43	 *   label: string,
44	 *   prevQuarterLabel: string,
45	 * }}
46	 */
47	export function getQuarterInfo(isoDate) {
48	  const [y, m] = isoDate.split('-').map(Number);
49	  const q = Math.ceil(m / 3);
50	
51	  const startMonth = (q - 1) * 3 + 1;
52	  const endMonth   = q * 3;
53	
54	  const start = `${y}-${String(startMonth).padStart(2, '0')}-01`;
55	  const lastDay = new Date(y, endMonth, 0).getDate(); // day 0 of next month = last day of this month
56	  const end   = `${y}-${String(endMonth).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
57	
58	  const totalDays =
59	    Math.round((new Date(end + 'T00:00:00') - new Date(start + 'T00:00:00')) / 86400000) + 1;
